func isBool(_ n: NSNumber) -> Bool {
    return CFGetTypeID(n) == CFBooleanGetTypeID()
}

func canonicalString(_ value: Any) -> String {
    if let dict = value as? [String: Any] {
        let keys = dict.keys.sorted()
        let parts = keys.map { "\"\(escapeString($0))\":\(canonicalString(dict[$0]!))" }
        return "{" + parts.joined(separator: ",") + "}"
    } else if let arr = value as? [Any] {
        return "[" + arr.map { canonicalString($0) }.joined(separator: ",") + "]"
    } else if let s = value as? String {
        return "\"\(escapeString(s))\""
    } else if let n = value as? NSNumber {
        if isBool(n) { return n.boolValue ? "true" : "false" }
        return "\(n)"
    } else if value is NSNull {
        return "null"
    }
    return "\(value)"
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var result = aDict
        for (key, bVal) in bDict {
