function httpGet(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const req = http.get(url, (res) => {
      let data = "";
      res.on("data", (chunk: string) => {
        data += chunk;
      });
      res.on("end", () => {
        resolve(data);
      });
      res.on("error", (err: Error) => {
        reject(err);
      });
    });
    req.on("error", (err: Error) => {
      reject(err);
    });
  });
}

