    return (char *)s;
}

static char *json_parse_string(const char *s, char **out) {
    s = json_skip_ws(s);
    if (*s != '"') return NULL;
    s++;
    const char *start = s;
    while (*s && *s != '"') {
        if (*s == '\\') s++;
        s++;
    }
    size_t len = (size_t)(s - start);
    *out = (char *)malloc(len + 1);
    size_t j = 0;
    const char *p = start;
    while (p < s) {
        if (*p == '\\') {
            p++;
            switch (*p) {
                case '"': (*out)[j++] = '"'; break;
                case '\\': (*out)[j++] = '\\'; break;
                case '/': (*out)[j++] = '/'; break;
                case 'n': (*out)[j++] = '\n'; break;
                case 't': (*out)[j++] = '\t'; break;
                case 'r': (*out)[j++] = '\r'; break;
                case 'b': (*out)[j++] = '\b'; break;
                case 'f': (*out)[j++] = '\f'; break;
                case 'u': {
                    /* simple unicode: just skip 4 hex digits */
                    p += 4;
                    (*out)[j++] = '?';
                    break;
                }
                default: (*out)[j++] = *p; break;
            }
            p++;
        } else {
            (*out)[j++] = *p++;
        }
    }
    (*out)[j] = '\0';
    if (*s == '"') s++;
    return (char *)s;
}

