    *out_len = sz;
    return buf;
}

static char *skip_ws(char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return p;
}

static char *parse_string(char *p, char *out, int max_len) {
    p = skip_ws(p);
    if (*p != '"') { fprintf(stderr, "Expected quote\n"); exit(1); }
    p++;
    int i = 0;
    while (*p && *p != '"') {
        if (*p == '\\') {
            p++;
            if (*p == 'n') out[i++] = '\n';
            else if (*p == 't') out[i++] = '\t';
            else out[i++] = *p;
        } else {
            out[i++] = *p;
        }
        p++;
        if (i >= max_len - 1) break;
    }
    out[i] = '\0';
    if (*p == '"') p++;
    return p;
}

static long long parse_number(char *p, char **end) {
    p = skip_ws(p);
    long long val = strtoll(p, end, 10);
    return val;
}

