func walk(_ path: String) -> [String] {
    var files: [String] = []
    let fm = FileManager.default
    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return files }
    for item in contents.sorted() {
        let fullPath = path + "/" + item
        var statInfo = stat()
        if lstat(fullPath, &statInfo) != 0 { continue }
        let fileType = statInfo.st_mode & S_IFMT
        if fileType == S_IFLNK { continue }
        if fileType == S_IFDIR {
            files.append(contentsOf: walk(fullPath))
        } else if fileType == S_IFREG {
            files.append(fullPath)
        }
    }
    return files
}

